/**
 * Seed script: Threat Hunt Sandbox datasets.
 *
 * Each dataset is a benign baseline with a deliberately planted attack chain,
 * generated by src/content/hunt-datasets.ts. Expected artifacts come from the
 * generator itself, so what the hunter is asked to find is guaranteed to be
 * present in the logs.
 *
 * Replaces an earlier version that emitted random field values — random event
 * IDs, and "evil.com" scattered through benign traffic — which left nothing
 * coherent to hunt.
 *
 * Usage: npm run seed:hunt-datasets
 */

import { PrismaClient } from "@prisma/client";
import {
  generateSysmonIntrusion,
  generateApacheWebshell,
  generateDnsDga,
  type GeneratedDataset,
} from "../src/content/hunt-datasets";

const db = new PrismaClient();

type DatasetSpec = {
  slug: string;
  name: string;
  description: string;
  difficulty: "EASY" | "MEDIUM" | "HARD";
  category: string;
  formatType: string;
  baseline: number;
  build: (n: number) => GeneratedDataset;
};

const DATASETS: DatasetSpec[] = [
  {
    slug: "sysmon-phishing-intrusion",
    name: "Sysmon — Phishing to Persistence",
    description:
      "A finance workstation opened an emailed document this morning. Nothing has alerted, but the host has been noisy since. Work out what ran, what it left behind, and where it is calling out to.",
    difficulty: "EASY",
    category: "SYSMON",
    formatType: "JSON",
    baseline: 3000,
    build: (n) => generateSysmonIntrusion(n),
  },
  {
    slug: "apache-webshell-hunt",
    name: "Apache — Web Shell on a Public Server",
    description:
      "Traffic to the public catalogue server looks ordinary in aggregate. One client does not. Find how they got a foothold and what they have been doing with it.",
    difficulty: "MEDIUM",
    category: "APACHE",
    formatType: "JSON",
    baseline: 20000,
    build: (n) => generateApacheWebshell(n),
  },
  {
    slug: "dns-dga-beaconing",
    name: "DNS — Algorithmic Domain Generation",
    description:
      "One host is resolving domains no human typed. Most of them fail. Identify the pattern well enough that it could be written as a detection.",
    difficulty: "HARD",
    category: "DNS",
    formatType: "JSON",
    baseline: 30000,
    build: (n) => generateDnsDga(n),
  },
];

async function seedDatasets() {
  console.log("\nSeeding Threat Hunt datasets\n");

  let created = 0;
  let skipped = 0;

  for (const spec of DATASETS) {
    const existing = await db.huntDataset.findUnique({ where: { slug: spec.slug } });
    if (existing) {
      console.log(`${spec.name}: already exists, skipping`);
      skipped++;
      continue;
    }

    const { logs, expectedArtifacts } = spec.build(spec.baseline);

    await db.huntDataset.create({
      data: {
        slug: spec.slug,
        name: spec.name,
        description: spec.description,
        difficulty: spec.difficulty,
        category: spec.category,
        formatType: spec.formatType,
        logCount: logs.length,
        expectedArtifacts,
        dataEmbedded: JSON.stringify(logs),
        published: true,
      },
    });

    console.log(
      `${spec.name}: ${logs.length.toLocaleString()} logs, ` +
        `${expectedArtifacts.length} artifacts to find`,
    );
    created++;
  }

  console.log(`\n${created} datasets created, ${skipped} already present.\n`);
  await db.$disconnect();
}

seedDatasets().catch(async (err) => {
  console.error("Hunt dataset seed failed:", err);
  await db.$disconnect();
  process.exit(1);
});
